def split_csv(line):
    """
    Parse one line of CSV and return its fields as a list of strings.
    Returns None if the line is malformed.
    """
    fields = []
    i = 0

    while i < len(line):
        if line[i] == '"':
            # Quoted field
            i += 1
            field = []
            while i < len(line):
                if line[i] == '"':
                    if i + 1 < len(line) and line[i + 1] == '"':
                        # Doubled quote represents a single quote
                        field.append('"')
                        i += 2
                    else:
                        # End of quoted field
                        i += 1
                        break
                else:
                    field.append(line[i])
                    i += 1
            else:
                # Reached end of line without closing quote
                return None

            # After closing quote, must be comma or end of line
            if i < len(line) and line[i] != ',':
                return None

            fields.append(''.join(field))

            # Move past comma if present
            if i < len(line) and line[i] == ',':
                i += 1

        else:
            # Unquoted field
            field = []
            while i < len(line) and line[i] != ',':
                if line[i] == '"':
                    # Unquoted field must not contain double quote
                    return None
                field.append(line[i])
                i += 1

            fields.append(''.join(field))

            # Move past comma if present
            if i < len(line) and line[i] == ',':
                i += 1

    return fields

